insert into public.item_options(item_id,option_key,content_hy,display_order)
select i.id,o.option_key,o.content_hy,o.display_order
from opts o join public.items i on i.code=o.code
on conflict(item_id,option_key) do update set
  content_hy=excluded.content_hy,
  display_order=excluded.display_order;
